import {profile,projects,certificates} from './content.js';
import {motionPreference} from './preferences.js';
import {setupPlayer} from './player.js';
import {setupMotion,animateIn} from './motion.js';
const $=s=>document.querySelector(s),reduced=()=>motionPreference.matches;
let soundOn=false,audio,master,filmPlaying=false,lastSound=-Infinity,voices=0;
try{soundOn=localStorage.getItem('sadman-sound')==='on'}catch{}
const soundButton=$('#sound');function updateSound(){soundButton.setAttribute('aria-pressed',String(soundOn));soundButton.setAttribute('aria-label',soundOn?'Mute interface sound':'Enable interface sound');soundButton.textContent=soundOn?'Sound on ◉':'Sound off ◌';if(master)master.gain.setTargetAtTime(soundOn?.12:0,audio.currentTime,.02);}updateSound();
async function unlock(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=soundOn?.12:0;master.connect(audio.destination);}if(audio.state==='suspended')await audio.resume();soundButton.dataset.audioState=audio.state;}catch{soundOn=false;updateSound();}}
function tone(kind='tap'){if(!soundOn||filmPlaying||!audio||audio.state!=='running'||voices>5)return;const now=audio.currentTime;if(now-lastSound<(kind==='hover'?.24:.12))return;lastSound=now;const notes=kind==='open'?[392,587]:kind==='close'?[294]:kind==='intro'?[294,440,587]:kind==='success'?[523,784]:kind==='hover'?[720]:kind==='nav'?[440,523]:[520];notes.forEach((freq,i)=>{const osc=audio.createOscillator(),gain=audio.createGain(),t=now+i*.065;voices++;osc.type='sine';osc.frequency.setValueAtTime(freq,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(kind==='hover'?.035:.15,t+.01);gain.gain.exponentialRampToValueAtTime(.0001,t+.16);osc.connect(gain);gain.connect(master);osc.start(t);osc.stop(t+.18);osc.onended=()=>{voices--;osc.disconnect();gain.disconnect();};});}
soundButton.addEventListener('click',async()=>{soundOn=!soundOn;if(soundOn)await unlock();updateSound();try{localStorage.setItem('sadman-sound',soundOn?'on':'off')}catch{}if(soundOn)tone('intro');toast(soundOn?'Interface sound enabled':'Interface sound muted');});
document.addEventListener('pointerdown',()=>{if(soundOn)void unlock()},{once:true});document.addEventListener('keydown',()=>{if(soundOn)void unlock()},{once:true});document.addEventListener('click',e=>{if(e.target.closest('a,button')&&!e.target.closest('#sound,.reel-controls,.reel-play'))tone(e.target.closest('nav')?'nav':'tap');});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
const menu=$('#menu');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');$('nav').classList.remove('open');}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('nav').classList.toggle('open',open);});$('nav').addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
function projectArt(p){return p.class==='cinedesk'?'<div class="device-art browser-art" aria-hidden="true"><div class="device-top"><i></i><i></i><i></i></div><div class="frame-grid"><span>01</span><span>02</span><span>03</span><span>04</span></div><div class="device-caption">SCENES / SHOTS / SCHEDULES</div></div>':'<div class="device-art phone-art" aria-hidden="true"><div class="phone-notch"></div><span class="phone-monogram">F<br><i>M</i>S.</span><div class="phone-line"></div><div class="phone-line short"></div></div>';}
$('#projects').innerHTML=projects.map((p,i)=>`<article class="project" data-kind="${p.kind}"><div class="project-visual ${p.class}"><span class="project-wordmark">${p.title}${i===0?'<span style="color:#c9b3ff">.</span>':''}</span>${projectArt(p)}<div class="project-headline">${p.headline}</div><span class="visual-note">${p.kind.toUpperCase()} / ${p.year}</span></div><div class="project-body"><span class="project-meta">${p.number} / ${p.kind.toUpperCase()}</span><h3>${p.title}</h3><p>${p.description}</p><button class="project-button" data-project="${i}" data-cursor="OPEN">Explore project <span>↗</span></button></div></article>`).join('');
$('.project-filters').addEventListener('click',e=>{const b=e.target.closest('[data-project-filter]');if(!b)return;$('.project-filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;$('#projects').querySelectorAll('.project').forEach(el=>{el.hidden=b.dataset.projectFilter!=='All'&&el.dataset.kind!==b.dataset.projectFilter;if(!el.hidden){count++;el.classList.add('visible');animateIn(el,count*.05);}});$('#project-status').textContent=`Showing ${count} projects`;});
const dialog=$('#detail'),dialogContent=$('#dialog-content');let returnFocus,closing=false,selectedCertificate=null,certificateZoom=100;
function showDialog(label,kind){returnFocus=document.activeElement;$('#dialog-label').textContent=label;dialog.dataset.kind=kind;dialog.classList.remove('closing');dialog.showModal();document.body.classList.add('no-scroll');tone('open');$('#close-dialog').focus();if(!reduced())dialog.animate([{opacity:0,transform:'translateY(24px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:380,easing:'cubic-bezier(.2,.75,.2,1)'});}
async function closeDialog(){if(closing||!dialog.open)return;closing=true;dialog.classList.add('closing');if(!reduced()){try{await dialog.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(15px) scale(.98)'}],{duration:190,easing:'ease-in',fill:'forwards'}).finished;}catch{}}dialog.getAnimations().forEach(a=>a.cancel());dialog.close();closing=false;}
$('#close-dialog').onclick=closeDialog;dialog.addEventListener('cancel',e=>{e.preventDefault();void closeDialog();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)void closeDialog();}});dialog.addEventListener('close',()=>{document.body.classList.remove('no-scroll');dialog.classList.remove('closing');returnFocus?.focus({preventScroll:true});selectedCertificate=null;tone('close');});
$('#projects').addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects[Number(b.dataset.project)];dialogContent.innerHTML=`<article class="project-detail"><div class="detail-art ${p.class}" aria-hidden="true">${projectArt(p)}<span>${p.number}</span></div><div class="detail-copy"><p class="eyebrow">${p.kind} / ${p.year} / ${p.role}</p><h2 id="modal-title">${p.title}</h2><p>${p.description}</p>${p.url?`<a class="button primary magnetic" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.link}</a>`:''}</div></article>`;dialog.setAttribute('aria-labelledby','modal-title');showDialog('SELECTED WORK / '+p.number,'project');});
let category='All',query='',galleryView='grid',shownCertificates=[];$('#certificate-total').textContent=certificates.length;const categories=['All',...new Set(certificates.map(c=>c.category))];$('#filters').innerHTML=categories.map(c=>`<button data-category="${c}" aria-pressed="${c==='All'}">${c}${c==='All'?' / '+certificates.length:''}</button>`).join('');
function renderCertificates(){shownCertificates=certificates.filter(c=>(category==='All'||c.category===category)&&`${c.title} ${c.issuer} ${c.date} ${c.detail}`.toLowerCase().includes(query));$('#results-status').textContent=`Showing ${shownCertificates.length} of ${certificates.length} credentials`;$('#certificate-grid').innerHTML=shownCertificates.length?shownCertificates.map(c=>`<button class="certificate-card" data-certificate="${c.id}" data-cursor="VIEW" aria-label="View ${c.title} certificate"><div class="certificate-image"><img src="assets/${c.id}.webp" width="600" height="440" loading="lazy" alt="${c.title} certificate issued to Sadman Labib Chowdhury"><span class="certificate-shine" aria-hidden="true"></span><span class="expand" aria-hidden="true">↗</span></div><div class="certificate-category"><span>${c.category}</span><span>${c.year}</span></div><h3>${c.title}</h3><p>${c.issuer}</p></button>`).join(''):'<p class="empty">No credentials match your search. Try another term or category.</p>';$('#certificate-grid').querySelectorAll('.certificate-card').forEach((el,i)=>animateIn(el,Math.min(i*.035,.22)));updateGalleryArrows();}
renderCertificates();$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderCertificates();});$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();renderCertificates();});
function updateGalleryArrows(){const el=$('#certificate-grid');$('#gallery-back').disabled=el.scrollLeft<2;$('#gallery-forward').disabled=el.scrollLeft+el.clientWidth>=el.scrollWidth-2;}
$('.gallery-view').addEventListener('click',e=>{const b=e.target.closest('[data-gallery-view]');if(!b)return;galleryView=b.dataset.galleryView;$('.gallery-view').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#certificate-grid').classList.toggle('filmstrip',galleryView==='filmstrip');$('.gallery-arrows').hidden=galleryView!=='filmstrip';$('#certificate-grid').scrollLeft=0;updateGalleryArrows();animateIn($('#certificate-grid'));});
for(const [id,direction]of [['#gallery-back',-1],['#gallery-forward',1]])$(id).onclick=()=>$('#certificate-grid').scrollBy({left:direction*$('#certificate-grid').clientWidth*.8,behavior:reduced()?'instant':'smooth'});$('#certificate-grid').addEventListener('scroll',updateGalleryArrows,{passive:true});addEventListener('resize',updateGalleryArrows,{passive:true});
function renderCertificate(id){const c=certificates.find(c=>c.id===id);if(!c)return;selectedCertificate=id;certificateZoom=100;const index=shownCertificates.findIndex(x=>x.id===id),focusId=document.activeElement?.id;dialogContent.innerHTML=`<div class="viewer-tools"><div class="viewer-navigation"><button id="certificate-previous" aria-label="Previous certificate" ${shownCertificates.length<2?'disabled':''}>←</button><span id="certificate-position" aria-live="polite">${index+1} / ${shownCertificates.length}</span><button id="certificate-next" aria-label="Next certificate" ${shownCertificates.length<2?'disabled':''}>→</button></div><div class="viewer-zoom"><button id="zoom-out" aria-label="Zoom certificate out">−</button><span id="zoom-level" aria-live="polite">100%</span><button id="zoom-in" aria-label="Zoom certificate in">+</button><button id="zoom-reset">Fit</button></div><a href="assets/${c.original}" target="_blank" rel="noopener noreferrer">Open original ↗</a></div><div class="image-viewer" tabindex="0" aria-label="Certificate image; use zoom controls or browser pinch zoom"><div class="certificate-sheet"><img id="full-certificate" src="assets/${c.id}.webp" alt="${c.title} certificate for Sadman Labib Chowdhury"></div></div><div class="certificate-details"><h2 id="modal-title">${c.title}</h2><p>${c.issuer} · ${c.date}</p><p>${c.detail}</p></div>`;
const apply=()=>{$('.certificate-sheet').style.width=certificateZoom+'%';$('.certificate-sheet').style.height=certificateZoom+'%';$('#zoom-level').textContent=certificateZoom+'%';$('#zoom-out').disabled=certificateZoom===100;$('#zoom-in').disabled=certificateZoom===300;};$('#zoom-in').onclick=()=>{certificateZoom=Math.min(300,certificateZoom+25);apply();};$('#zoom-out').onclick=()=>{certificateZoom=Math.max(100,certificateZoom-25);apply();};$('#zoom-reset').onclick=()=>{certificateZoom=100;apply();};$('#certificate-previous').onclick=()=>navigateCertificate(-1);$('#certificate-next').onclick=()=>navigateCertificate(1);apply();if(dialog.open&&focusId&&$('#'+focusId))$('#'+focusId).focus({preventScroll:true});animateIn($('.image-viewer'));}
function navigateCertificate(direction){if(shownCertificates.length<2)return;const index=shownCertificates.findIndex(c=>c.id===selectedCertificate);renderCertificate(shownCertificates[(index+direction+shownCertificates.length)%shownCertificates.length].id);tone('open');}
$('#certificate-grid').addEventListener('click',e=>{const b=e.target.closest('[data-certificate]');if(!b)return;renderCertificate(b.dataset.certificate);dialog.setAttribute('aria-labelledby','modal-title');showDialog('CREDENTIAL GALLERY','certificate');});
let touchStart;dialogContent.addEventListener('touchstart',e=>{if(selectedCertificate&&certificateZoom===100&&e.touches.length===1&&e.target.closest('.image-viewer'))touchStart=[e.touches[0].clientX,e.touches[0].clientY];else touchStart=null;},{passive:true});dialogContent.addEventListener('touchend',e=>{if(!touchStart||!e.changedTouches.length)return;const dx=e.changedTouches[0].clientX-touchStart[0],dy=e.changedTouches[0].clientY-touchStart[1];if(Math.abs(dx)>85&&Math.abs(dy)<45)navigateCertificate(dx<0?1:-1);touchStart=null;},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('nav').classList.contains('open')){closeMenu();menu.focus();}if(dialog.open&&selectedCertificate&&['ArrowLeft','ArrowRight'].includes(e.key)&&!(certificateZoom>100&&e.target.closest('.image-viewer'))){e.preventDefault();navigateCertificate(e.key==='ArrowRight'?1:-1);}});
setupPlayer({onPlayback:value=>filmPlaying=value,toast});
$('#copy-email').onclick=async()=>{try{await navigator.clipboard.writeText(profile.email);toast('Email address copied');tone('success');}catch{toast('Copy unavailable. Use the email link to get in touch.');}};
setupMotion({tone});
